def number_to_words(n):
    if type(n) is not int:
        raise ValueError("Input must be an integer")
    if not (0 <= n <= 999_999_999):
        raise ValueError("Integer out of range [0, 999999999]")
    # word lists
    units = ["zero","one","two","three","four","five","six","seven","eight","nine",
             "ten","eleven","twelve","thirteen","fourteen","fifteen","sixteen",
             "seventeen","eighteen","nineteen"]
    tens = ["","","twenty","thirty","forty","fifty","sixty","seventy","eighty","ninety"]
    def under_thousand(num):
        if num < 20:
            return units[num]
        elif num < 100:
            ten = tens[num//10]
            unit = num%10
            return ten + ("-" + units[unit] if unit else "")
        else:
            hundred = units[num//100] + " hundred"
            rest = num%100
            if rest:
                return hundred + " " + under_thousand(rest)
            else:
                return hundred
    if n == 0:
        return units[0]
    parts = []
    millions = n // 1_000_000
    if millions:
        parts.append(under_thousand(millions) + " million")
        n %= 1_000_000
    thousands = n // 1_000
    if thousands:
        parts.append(under_thousand(thousands) + " thousand")
        n %= 1_000
    if n:
        parts.append(under_thousand(n))
    return " ".join(parts)

